insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ssresearch_v1'
from (values
('113.48.c.1.A',3,'Which topic is narrow enough for a social science research project?','["How did the 1936 Texas Centennial affect tourism in Dallas?", "History", "What happened in the world?", "Why do people live in cities?"]'::jsonb,0,'A focused topic can be researched in depth.','original'),
('113.48.c.1.A',3,'A good way to choose a research topic is to do what?','["Copy a classmate''s topic", "Pick an issue that interests you and has available sources", "Choose the biggest topic possible", "Pick one with no evidence"]'::jsonb,1,'Interest and available evidence sustain research.','original'),
('113.48.c.1.B',3,'A research rationale explains what?','["Who the author is", "The font style", "Why the topic is worth studying", "The length of the paper"]'::jsonb,2,'It justifies the project.','original'),
('113.48.c.1.B',3,'Preliminary ideas for research methods include deciding what?','["What color to print in", "Which friend to cite", "Where to eat lunch", "How you will gather and analyze information"]'::jsonb,3,'Methods are planned early.','original'),
('113.48.c.1.C',3,'A literature review is a summary of what?','["What scholars have already written about the topic", "A list of survey questions", "Future predictions", "The student''s opinions"]'::jsonb,0,'It shows what is known and where the gaps are.','original'),
('113.48.c.1.C',3,'A literature review helps a researcher by doing what?','["Proving the thesis automatically", "Showing a gap that the new study can fill", "Hiding earlier work", "Replacing the research"]'::jsonb,1,'Reviews place a study in context.','original'),
('113.48.c.1.D',3,'A research thesis should be what?','["A fact everyone knows", "A list of questions", "An arguable claim that evidence can support or test", "A quote from a source"]'::jsonb,2,'A thesis guides the study.','original'),
('113.48.c.1.D',3,'Which is the best research thesis?','["Schools exist.", "Texas is large.", "Migration is interesting.", "Rural-to-urban migration after 1940 increased Texas school enrollment in cities more than in counties."]'::jsonb,3,'It is specific and testable.','original'),
('113.48.c.2.A',3,'Quantitative research methods primarily collect what?','["Numerical data that can be measured and analyzed statistically", "Only stories and quotes", "Only images", "Only opinions without numbers"]'::jsonb,0,'Qualitative research collects descriptive data.','original'),
('113.48.c.2.A',3,'Qualitative research methods emphasize what?','["Only large datasets", "Meaning, context and descriptions from sources such as interviews", "Only experiments", "Only computation"]'::jsonb,1,'Interviews and observation are common.','original'),
('113.48.c.2.B',3,'Designing a research project involves choosing what?','["A random paper size", "A title only", "A question, a theory and methods that fit the question", "A random date"]'::jsonb,2,'Design connects question and method.','original'),
('113.48.c.2.B',3,'Which research question requires a survey method?','["Where is a river located?", "Who wrote a diary in 1800?", "What did a 1950 treaty say?", "What percent of students at a school support a later start time?"]'::jsonb,3,'Surveys measure attitudes in a sample.','original'),
('113.48.c.2.C',3,'Which technique collects oral information from people?','["Interviews", "Atlas maps", "Census tables", "Encyclopedias"]'::jsonb,0,'Oral sources include interviews and oral histories.','original'),
('113.48.c.2.C',3,'A researcher who watches behavior in a natural setting without changing it is using what?','["Survey sampling", "Observation", "Experiments", "Literature review"]'::jsonb,1,'Observation records behavior as it occurs.','original'),
('113.48.c.2.D',3,'Which technology would help a researcher locate scholarly articles?','["A shopping website", "A music streaming app", "An academic journal database", "A video game"]'::jsonb,2,'Databases index peer-reviewed work.','original'),
('113.48.c.2.D',3,'When searching online, a researcher should prefer which kind of source?','["Anonymous posts", "Rumor pages", "Advertisements", "Scholarly and government sites with identifiable authors"]'::jsonb,3,'Credibility depends on authorship and review.','original'),
('113.48.c.2.E',3,'Using sources that show multiple perspectives helps a researcher do what?','["Avoid a one-sided view of the topic", "Remove evidence", "Shorten the project", "Avoid analysis"]'::jsonb,0,'Multiple perspectives reduce bias.','original'),
('113.48.c.2.E',3,'A study of a labor strike that uses only management records is likely to be what?','["Fully objective", "Incomplete because it omits workers'' perspectives", "Quantitative", "Perfectly balanced"]'::jsonb,1,'Both sides should be represented.','original'),
('113.48.c.2.F',3,'A researcher reading a senator''s personal journal from 1862 is using what type of source?','["A tertiary source", "A secondary source", "A primary source", "A textbook"]'::jsonb,2,'It was created by a participant at the time.','original'),
('113.48.c.2.F',3,'A scholarly book that interprets primary documents is what type of source?','["An artifact", "A raw dataset", "A primary source", "A secondary source"]'::jsonb,3,'Secondary sources analyze and interpret.','original'),
('113.48.c.2.G',3,'Which is a useful criterion for evaluating a source?','["Author expertise, evidence quality and timeliness", "Page color", "Number of images", "Length of title"]'::jsonb,0,'Criteria help judge reliability.','original'),
('113.48.c.2.G',3,'When evaluating numerical information, a researcher should check what?','["The paper weight", "How the data were collected and the sample size", "The cover design", "The font"]'::jsonb,1,'Method affects trustworthiness.','original'),
('113.48.c.2.H',3,'Describing the results of research means doing what?','["Changing the numbers", "Hiding unexpected results", "Reporting what the data showed without overstating", "Skipping the findings"]'::jsonb,2,'Results are described objectively.','original'),
('113.48.c.2.H',3,'A results section should present findings in what form?','["Rumors", "A long quote only", "A guess", "Clear text supported by tables or charts"]'::jsonb,3,'Visuals clarify the findings.','original'),
('113.48.c.2.I',3,'A logical conclusion should be what?','["Drawn directly from the research results", "Formed before research began", "Based on assumptions only", "Unrelated to the data"]'::jsonb,0,'Conclusions follow evidence.','original'),
('113.48.c.2.I',3,'If a survey shows 78 percent of respondents favor a policy, which conclusion is logical?','["Everyone in the world favors it", "Most respondents in the sample favor the policy", "No one opposes it", "The policy will pass"]'::jsonb,1,'Conclusions must match the data and sample.','original'),
('113.48.c.2.J',3,'Justifying a conclusion requires what?','["A long introduction", "Repeating the thesis", "Supporting evidence from the research", "Strong opinion"]'::jsonb,2,'Evidence backs claims.','original'),
('113.48.c.2.J',3,'Which statement best justifies a conclusion?','["It seems right.", "A friend agrees.", "The author feels sure.", "Three independent sources and the survey data point to the same result."]'::jsonb,3,'Convergent evidence strengthens a conclusion.','original'),
('113.48.c.2.K',3,'Making a prediction from research means doing what?','["Using findings to suggest likely future outcomes", "Guessing without data", "Changing the data", "Ignoring trends"]'::jsonb,0,'Predictions extend from conclusions.','original'),
('113.48.c.2.K',3,'If data show enrollment rising steadily for ten years, a reasonable prediction is what?','["Enrollment is unrelated to time", "Enrollment will likely continue to rise if conditions stay similar", "Enrollment will fall tomorrow", "Enrollment cannot be predicted"]'::jsonb,1,'Trend extrapolation has limits.','original'),
('113.48.c.2.L',3,'MLA and APA are examples of what?','["Types of graphs", "Statistical tests", "Citation styles for social science writing", "Survey methods"]'::jsonb,2,'Style guides format bibliographies.','original'),
('113.48.c.2.L',3,'A bibliography entry usually includes which information?','["Only the date", "Only the title", "A summary", "Author, title, publisher and date"]'::jsonb,3,'Entries let readers find the source.','original'),
('113.48.c.3.A',3,'Historiography is the study of what?','["How historians have interpreted and written about a topic over time", "Biographies only", "Future trends", "Weather records"]'::jsonb,0,'Interpretations change with new evidence and views.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ssresearch_v1'
from (values
('113.48.c.3.A',3,'Why do historians interpret the same event differently over time?','["Sources disappear", "New evidence and changing perspectives shape interpretations", "Facts never change", "Historians avoid the topic"]'::jsonb,1,'Historiography reflects shifting viewpoints.','original'),
('113.48.c.3.B',3,'Causality in social science research refers to what?','["A type of map", "A list of dates", "The relationship in which one factor produces an effect", "A bibliography style"]'::jsonb,2,'Researchers test causal claims carefully.','original'),
('113.48.c.3.B',3,'Which key concept refers to how things stay the same or alter across time?','["Citation", "Rhetoric", "Sampling", "Continuity and change"]'::jsonb,3,'Time and change are central concepts.','original'),
('113.48.c.3.C',3,'Analyzing viewpoints within and across cultures requires a researcher to do what?','["Consider how culture and context shape beliefs", "Apply only modern values", "Ignore other cultures", "Judge them all the same"]'::jsonb,0,'Context explains differing viewpoints.','original'),
('113.48.c.3.C',3,'Two cultures describe the same border dispute differently. A researcher should do what?','["Choose the louder account", "Examine sources from both sides and compare their viewpoints", "Use only one", "Reject both accounts"]'::jsonb,1,'Comparison yields a fuller analysis.','original'),
('113.48.c.3.D',3,'A recurring dilemma in social science is the conflict between what?','["Two colors", "Two seasons", "Individual liberty and the common good", "Two fonts"]'::jsonb,2,'Such dilemmas recur across eras.','original'),
('113.48.c.3.D',3,'A persistent issue relevant to many topics is what?','["The color of the sky", "The invention of the pencil", "Daily weather", "Unequal distribution of resources and power"]'::jsonb,3,'Persistent issues connect topics across time.','original'),
('113.48.c.3.E',3,'Skepticism in research means what?','["Questioning claims and requiring evidence", "Avoiding conclusions", "Rejecting all sources", "Believing everything"]'::jsonb,0,'Healthy doubt improves analysis.','original'),
('113.48.c.3.E',3,'Historical empathy means doing what?','["Judging only by today", "Trying to understand people of the past within their own context", "Ignoring evidence", "Excusing all actions"]'::jsonb,1,'Empathy helps interpretation without losing critical judgment.','original'),
('113.48.c.4.A',3,'The first step of the scientific method in a research project is usually what?','["Draw a conclusion", "Publish results", "Ask a question or identify a problem", "Write the bibliography"]'::jsonb,2,'Research begins with a question.','original'),
('113.48.c.4.A',3,'A hypothesis in the scientific method is what?','["A random guess", "A proven law", "A bibliography", "A testable prediction about a relationship"]'::jsonb,3,'It is tested with data.','original'),
('113.48.c.4.B',3,'A research methods matrix is used to do what?','["Compare which methods suit different research questions", "Write a conclusion", "Hide data", "Replace sources"]'::jsonb,0,'Matrices organize method choices.','original'),
('113.48.c.4.B',3,'Which method fits the study of a community''s customs by living among its members?','["Statistical modeling", "Ethnography", "Content coding", "Survey research"]'::jsonb,1,'Ethnography uses immersion.','original'),
('113.48.c.4.C',3,'The most efficient research approach is the one that does what?','["Avoids data", "Takes the longest", "Answers the question with the needed evidence at reasonable cost and time", "Uses the most sources"]'::jsonb,2,'Efficiency weighs time, cost and fit.','original'),
('113.48.c.4.C',3,'A researcher needing opinions from 500 students quickly should most likely use what?','["Ethnography", "Archival research", "A case study", "A survey"]'::jsonb,3,'Surveys reach many people efficiently.','original'),
('113.48.c.4.D',3,'Aggregate information refers to what?','["Data combined from many individuals or units", "A single interview", "One person''s diary", "A personal letter"]'::jsonb,0,'Statistics summarize aggregate data.','original'),
('113.48.c.4.D',3,'Which tool helps summarize a large data set?','["A map legend only", "Statistical measures such as mean and median", "A rhyme scheme", "A footnote"]'::jsonb,1,'Basic statistics describe data.','original'),
('113.48.c.4.E',3,'The mean of 4, 6, 8 and 10 is what?','["6", "8", "7", "28"]'::jsonb,2,'Sum 28 divided by 4 equals 7.','original'),
('113.48.c.4.E',3,'A positive correlation means that what is true?','["One causes the other", "They never move together", "As one rises, the other falls", "As one variable rises, the other tends to rise"]'::jsonb,3,'Correlation is not causation.','original'),
('113.48.c.4.F',3,'Which software can be used to compute averages and make charts from survey data?','["A spreadsheet program", "A calendar only", "A photo editor only", "A game console"]'::jsonb,0,'Spreadsheets analyze data.','original'),
('113.48.c.4.F',3,'Statistical analysis software is helpful because it does what?','["Chooses the thesis", "Processes large data sets quickly and accurately", "Creates the evidence", "Removes bias automatically"]'::jsonb,1,'Tools speed analysis but do not replace judgment.','original'),
('113.48.c.4.G',3,'Reliability in research refers to what?','["Length of the paper", "Popularity of findings", "Consistency of results when a study is repeated", "Accuracy of the topic choice"]'::jsonb,2,'Reliable measures yield consistent results.','original'),
('113.48.c.4.G',3,'Validity in research refers to what?','["Consistency alone", "The number of pages", "The sample''s age", "Whether a study measures what it claims to measure"]'::jsonb,3,'Valid measures are accurate.','original'),
('113.48.c.4.H',3,'Cross-cultural understanding is obstructed by what?','["Ethnocentric attitudes and stereotypes", "Curiosity", "Open dialogue", "Respect"]'::jsonb,0,'Biased attitudes block understanding.','original'),
('113.48.c.4.H',3,'A researcher studying greetings across cultures should expect what?','["No cultural influence", "Behavior patterns to reflect each culture''s values", "Only individual differences", "All greetings to be identical"]'::jsonb,1,'Values shape behavior.','original'),
('113.48.c.4.I',3,'Before surveying human participants, researchers should obtain what?','["A prize", "A refund", "Informed consent", "A grade"]'::jsonb,2,'Participants must know and agree.','original'),
('113.48.c.4.I',3,'Ethical standards for storing survey data require what?','["Posting names publicly", "Sharing with anyone", "Selling data", "Protecting participants'' privacy and keeping data secure"]'::jsonb,3,'Confidentiality is essential.','original'),
('113.48.c.5.A',3,'Which sentence uses standard written English?','["The data support the researcher''s conclusion.", "the data support the researcher''s conclusion", "The datas support the researcher''s conclusion.", "The data supports the researchers conclusion"]'::jsonb,0,'Usage and mechanics matter in research writing.','original'),
('113.48.c.5.A',3,'Editing a research draft helps to do what?','["Add new sources", "Improve clarity, grammar and organization", "Change the topic", "Remove the thesis"]'::jsonb,1,'Revision polishes a paper.','original'),
('113.48.c.5.B',3,'Where does a research paper typically state its thesis?','["On the cover", "In the footnote", "In the introduction", "Only in the bibliography"]'::jsonb,2,'The thesis frames the paper.','original'),
('113.48.c.5.B',3,'The conclusion of a research paper should do what?','["Introduce unrelated topics", "Apologize for the study", "Add new data", "Restate the thesis and summarize the findings"]'::jsonb,3,'It closes the argument.','original'),
('113.48.c.5.C',3,'Which term means a systematic way of collecting data from a group?','["Survey", "Map", "Footnote", "Thesis"]'::jsonb,0,'Accurate terminology aids communication.','original'),
('113.48.c.5.C',3,'Using social science terminology correctly shows what?','["Disinterest", "Understanding of the field''s concepts", "Disorganization", "Complexity for its own sake"]'::jsonb,1,'Precision builds credibility.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ssresearch_v1'
from (values
('113.48.c.5.D',3,'Addressing a counter argument shows that a researcher has done what?','["Hidden the sources", "Ignored evidence", "Considered opposing evidence and responded to it", "Changed the thesis"]'::jsonb,2,'It strengthens the argument.','original'),
('113.48.c.5.D',3,'Which approach best justifies a conclusion while addressing objections?','["Insulting critics", "Repeating the claim", "Refusing to discuss opposition", "Presenting evidence and explaining why opposing claims are weaker"]'::jsonb,3,'Rebuttal with evidence persuades.','original'),
('113.48.c.5.E',3,'A timeline is best used to show what?','["Events in chronological order", "Percentages of a whole", "Relationships between two variables", "Geographic locations"]'::jsonb,0,'It displays sequence.','original'),
('113.48.c.5.E',3,'Which visual best shows the parts of a whole such as budget shares?','["A flowchart", "A pie chart", "A timeline", "A scatter plot"]'::jsonb,1,'Pie charts show proportions.','original'),
('113.48.c.5.F',3,'Presentation software lets a researcher do what?','["Review literature", "Collect primary data", "Combine text, graphics and multimedia to share findings", "Replace research"]'::jsonb,2,'Software aids communication of results.','original'),
('113.48.c.5.F',3,'A strong slide in a research presentation includes what?','["Unrelated clip art", "A wall of text", "No labels", "A clear point supported by a simple visual"]'::jsonb,3,'Clarity helps the audience.','original'),
('113.48.c.5.G',3,'Visual images in a presentation should be what?','["Relevant to the topic and properly credited", "Distracting", "Uncredited", "Random"]'::jsonb,0,'Images should enhance the message.','original'),
('113.48.c.5.G',3,'An archival photograph can enhance a presentation by doing what?','["Removing the need for sources", "Making historical context more vivid for the audience", "Proving the thesis alone", "Replacing the evidence"]'::jsonb,1,'Visual evidence adds depth.','original'),
('113.48.c.5.H',3,'A works cited list is used for what?','["Writing the thesis", "Hiding evidence", "Showing the sources that supplied the paper''s ideas and data", "Making a graph"]'::jsonb,2,'Attribution is a basic research standard.','original'),
('113.48.c.5.H',3,'Which practice avoids plagiarism?','["Copying and pasting without credit", "Changing a few words", "Using only one source", "Citing every source whose ideas or words you use"]'::jsonb,3,'Credit sources properly.','original'),
('113.48.c.6.A',3,'For a capstone research project, a student should select what?','["A social studies issue that can be studied with available evidence", "The longest topic", "A topic with no sources", "An unresearchable topic"]'::jsonb,0,'Topic selection starts the project.','original'),
('113.48.c.6.A',3,'An area of interest becomes a research topic when it is what?','["Copied", "Narrowed into a focused, researchable question", "Left broad", "Dropped"]'::jsonb,1,'Focus makes research manageable.','original'),
('113.48.c.6.B',3,'A well-designed capstone project examines what?','["Only formatting", "Only the conclusion", "The theory and methods that fit the research question", "Only the introduction"]'::jsonb,2,'Fit between theory and method matters.','original'),
('113.48.c.6.B',3,'Why include a methods section in a capstone paper?','["To lengthen the paper", "To hide results", "To avoid a thesis", "So readers can see how evidence was collected and evaluate it"]'::jsonb,3,'Transparency allows evaluation.','original'),
('113.48.c.6.C',3,'Describing results in a capstone project means doing what?','["Explaining what the research found, supported by data", "Listing sources only", "Skipping data", "Making predictions only"]'::jsonb,0,'Results come before interpretation.','original'),
('113.48.c.6.D',3,'A strong capstone conclusion justifies its claim with evidence and also does what?','["Repeats the title", "Makes reasoned predictions about future outcomes", "Avoids implications", "Ignores limits"]'::jsonb,1,'Predictions extend findings.','original'),
('113.48.c.6.D',3,'A capstone paper claims a new law will reduce crime. Which evidence best justifies this claim?','["A single anecdote", "The author''s hope", "Crime data from similar places before and after comparable laws", "A slogan"]'::jsonb,2,'Comparable data support predictions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
